result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/server.py", "content": "#!/usr/bin/env python3
"""Educational dosing checker for invented drugs (pharmacy-tech training lab).

NOT for clinical use. All drugs are fictional.
"""
import json
from http.server import BaseHTTPRequestHandler, HTTPServer

HOST = "127.0.0.1"
PORT = 8077

# Fictional drug rules: max mg per kg per dose
DRUG_RULES = {
    "examplecillin": 30,
    "demomycin": 12,
}


def is_number(x):
    return isinstance(x, (int, float)) and not isinstance(x, bool)


class DoseHandler(BaseHTTPRequestHandler):
    def _send_json(self, code, payload):
        body = json.dumps(payload).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        if self.path != "/check-dose":
            self._send_json(404, {"error": "not found"})
            return
        try:
            length = int(self.headers.get("Content-Length", 0))
            raw = self.rfile.read(length)
            data = json.loads(raw)
            if not isinstance(data, dict):
                raise ValueError("body must be a JSON object")
        except (json.JSONDecodeError, ValueError, UnicodeDecodeError):
            self._send_json(400, {"error": "malformed JSON"})
            return

        for key in ("drug", "weight_kg", "dose_mg"):
            if key not in data:
                self._send_json(400, {"error": f"missing key: {key}"})
                return

        drug = data["drug"]
        weight = data["weight_kg"]
        dose = data["dose_mg"]

        if not isinstance(drug, str):
            self._send_json(400, {"error": "drug must be a string"})
            return
        if not (is_number(weight) and weight > 0):
            self._send_json(400, {"error": "weight_kg must be a positive number"})
            return
        if not (is_number(dose) and dose > 0):
            self._send_json(400, {"error": "dose_mg must be a positive number"})
            return

        drug_lower = drug.strip().lower()
        if drug_lower not in DRUG_RULES:
            self._send_json(400, {"error": f"unknown drug: {drug}"})
            return

        max_mg = DRUG_RULES[drug_lower] * weight
        if dose <= max_mg:
            self._send_json(200, {"status": "ok", "max_mg": max_mg})
        else:
            self._send_json(200, {"status": "exceeds_max", "max_mg": max_mg})

    def log_message(self, fmt, *args):
        pass  # keep output quiet


if __name__ == "__main__":
    HTTPServer((HOST, PORT), DoseHandler).serve_forever()
"})
